// ─── Tool executor ───────────────────────────────────────────────────────────

export async function executeMemoryTool(
  toolName: string,
  args: Record<string, unknown>,
  ctx: { userId: string },
): Promise<{ success: boolean; data: string } | null> {
  const userId = ctx.userId;

  switch (toolName) {
    case "memory_search": {
      const query = (args.query as string) ?? "";
      const results = await searchVectorMemories(userId, query, 5, 0.2);
      if (results.length === 0) {
        return { success: true, data: "Aucun souvenir trouvé pour cette recherche." };
      }
      const formatted = results
        .map((r, i) => `${i + 1}. [${Math.round(r.score * 100)}%] ${r.content.slice(0, 150)}`)
        .join("\n");
      return { success: true, data: `Souvenirs trouvés:\n${formatted}` };
    }

    case "memory_list": {
      const facts = await prisma.memoryFact.findMany({
        where: { userId },
        orderBy: { weight: "desc" },
        take: 25,
      });
      const embeddingCount = await prisma.memoryEmbedding.count({ where: { userId } });
      if (facts.length === 0 && embeddingCount === 0) {
        return { success: true, data: "Aucune mémoire enregistrée." };
      }
      const factList = facts
        .map((f) => `• ${f.key} (${f.category || "auto"}): ${f.value.slice(0, 100)}`)
        .join("\n");
      return {
        success: true,
        data: `${facts.length} fait(s) + ${embeddingCount} souvenir(s) vectoriel(s):\n${factList}`,
      };
    }

    case "memory_forget": {
      const key = (args.key as string) ?? "";
      if (key.toLowerCase() === "all") {
        const factsDeleted = await prisma.memoryFact.deleteMany({ where: { userId } });
        const embDeleted = await prisma.memoryEmbedding.deleteMany({ where: { userId } });
        return {
          success: true,
          data: `Mémoire effacée: ${factsDeleted.count} fait(s) + ${embDeleted.count} souvenir(s) supprimés.`,
        };
      }
      const deleted = await prisma.memoryFact.deleteMany({ where: { userId, key } });
      return {
        success: deleted.count > 0,
        data:
          deleted.count > 0 ? `Fait "${key}" supprimé.` : `Aucun fait trouvé avec la clé "${key}".`,
      };
    }

    case "persona_set": {
      const param = (args.param as string) ?? "custom";
      const value = (args.value as string) ?? "";
      const keyMap: Record<string, string> = {
        tone: "preferred_tone",
        language: "preferred_language",
        detail: "detail_level",
        custom: "custom_prompt",
      };
      const key = keyMap[param] ?? "custom_prompt";
      await setInstruction(userId, key, value);
      return {
        success: true,
        data: `Instruction personnalisée définie: ${param} = "${value.slice(0, 80)}"`,
      };
    }

    case "persona_list": {
      const instructions = await getCustomInstructions(userId);
      return {
        success: true,
        data: instructions || "Aucune instruction personnalisée définie.",
      };
    }

    case "persona_clear": {
      const param = (args.param as string) ?? "all";
      const keyMap: Record<string, string> = {
        tone: "preferred_tone",
        language: "preferred_language",
        detail: "detail_level",
        custom: "custom_prompt",
        all: "all",
      };
      const key = keyMap[param] ?? "all";
      if (key === "all") {
        await prisma.memoryFact.deleteMany({
          where: { userId, category: "custom_instruction" },
        });
        return { success: true, data: "Toutes les instructions personnalisées ont été effacées." };
      }
      const deleted = await clearInstruction(userId, key);
      return {
        success: deleted,
        data: deleted
          ? `Instruction "${param}" supprimée.`
          : `Aucune instruction trouvée pour "${param}".`,
      };
    }

    case "conversation_start": {
      const name = (args.name as string) ?? "session";
      const session = startSession(userId, name);
      return { success: true, data: `Conversation "${session.sessionName}" démarrée.` };
    }

    case "conversation_end": {
      const session = endSession(userId);
      return {
        success: session !== null,
        data: session
          ? `Conversation "${session.sessionName}" terminée (${session.messageCount} messages).`
          : "Aucune conversation active.",
      };
    }

    case "conversation_status": {
      const session = getActiveSession(userId);
      return {
        success: true,
        data: session
          ? `Conversation active: "${session.sessionName}" — ${session.messageCount} messages depuis ${session.startedAt.toLocaleString()}.`
          : "Aucune conversation active.",
      };
    }

    default:
      return null;
  }
}

/**
 * proactiveAgent.ts — Proactivité, apprentissage feedback, digest perso
 *
 * 1. Détecte les questions qui restent sans réponse dans un salon
 * 2. Adapte les prompts système selon les réactions feedback (👍/👎)
 * 3. Génère un digest hebdomadaire personnalisé par utilisateur
 */

import { Client, TextChannel, EmbedBuilder } from "discord.js";
import prisma from "../prisma.js";
import logger from "../utils/logger.js";
import { getOpenAIClient } from "./ai.js";
import { config } from "../config.js";

// ─── 1. Unanswered question detection ────────────────────────────────────────

interface UnansweredQuestion {
  channelId: string;
  messageId: string;
  authorId: string;
  content: string;
  timestamp: Date;
}

const QUESTION_PATTERNS = [
  /\?$/,
  /\b(comment|pourquoi|quand|où|comment faire|help|aide|quelqu'un sait|est-ce que)\b/i,
  /\b(how|why|when|where|what|can someone|anyone know|is there)\b/i,
];

const BOT_REPLY_INDICATORS = ["agent", "assistant", "bot", "ia", "ai"];

/**
 * Scanne les messages récents d'un salon et détecte les questions sans réponse.
 * Ne se déclenche que si le bot n'a pas déjà répondu dans les 5 minutes.
 */
export async function detectUnansweredQuestions(
  client: Client,
  guildId: string,
  channelId: string,
): Promise<UnansweredQuestion[]> {
  try {
    const channel = await client.channels.fetch(channelId).catch(() => null);
    if (!channel || !channel.isTextBased()) return [];

    const messages = await channel.messages.fetch({ limit: 30 });
    const now = Date.now();
    const unanswered: UnansweredQuestion[] = [];

    for (const [id, msg] of messages) {
      // Skip bot messages
      if (msg.author.bot) continue;
      // Skip messages older than 10 minutes
      if (now - msg.createdTimestamp > 10 * 60 * 1000) continue;

      // Check if it looks like a question
      const isQuestion = QUESTION_PATTERNS.some((p) => p.test(msg.content));
      if (!isQuestion) continue;

      // Check if the bot or another user replied within 5 minutes
      const replies = messages.filter(
        (m) =>
          m.createdTimestamp > msg.createdTimestamp &&
          m.createdTimestamp - msg.createdTimestamp < 5 * 60 * 1000 &&
          (m.author.bot || m.mentions?.has(msg.author.id)),
      );

      if (replies.size === 0) {
        unanswered.push({
          channelId,
          messageId: id,
          authorId: msg.author.id,
          content: msg.content.slice(0, 200),
          timestamp: new Date(msg.createdTimestamp),
        });
      }
    }

    return unanswered;
  } catch (err) {
    logger.debug(
      `[Proactive] detectUnansweredQuestions: ${err instanceof Error ? err.message : String(err)}`,
    );
    return [];
  }
}

/**
 * Tente de répondre proactivement à une question non répondue.
 */
export async function tryProactiveReply(
  client: Client,
  question: UnansweredQuestion,
): Promise<boolean> {
  try {
    const channel = await client.channels.fetch(question.channelId).catch(() => null);
    if (!channel || !("send" in channel)) return false;

    // Generate a brief helpful response
    const openai = getOpenAIClient();
    const completion = await openai.chat.completions.create({
      model: config.openRouterModel,
      messages: [
        {
          role: "system",
          content:
            "Tu es un assistant Discord proactif. Un utilisateur a posé une question qui est restée sans réponse. " +
            "Propose une réponse brève et utile. Si tu n'es pas sûr, dis-le. Réponds en français.",
        },
        { role: "user", content: question.content },
      ],
      max_tokens: 300,
      temperature: 0.5,
    });

    const reply = completion.choices[0]?.message?.content?.trim();
    if (!reply) return false;

    await (channel as TextChannel).send({
      content: `💡 <@${question.authorId}>, je viens de voir ta question qui est restée sans réponse. Voici ce que je peux suggérer:\n\n${reply}`,
      allowedMentions: { users: [question.authorId] },
    });

    logger.info(
      `[Proactive] Réponse proactive envoyée pour ${question.authorId} dans ${question.channelId}`,
    );
    return true;
  } catch (err) {
    logger.debug(
      `[Proactive] tryProactiveReply: ${err instanceof Error ? err.message : String(err)}`,
    );
    return false;
  }
}

// ─── 2. Feedback-based prompt adaptation ─────────────────────────────────────

interface FeedbackEntry {
  userId: string;
  toolName: string;
  positive: boolean;
  timestamp: Date;
}

const feedbackStore: FeedbackEntry[] = [];
const MAX_FEEDBACK_ENTRIES = 500;

export function recordFeedback(userId: string, toolName: string, positive: boolean): void {
  feedbackStore.push({ userId, toolName, positive, timestamp: new Date() });
  if (feedbackStore.length > MAX_FEEDBACK_ENTRIES) {
    feedbackStore.shift();
  }
  logger.info(`[Feedback] ${positive ? "👍" : "👎"} user=${userId} tool=${toolName}`);
}

/**
 * Génère des hints de prompt basés sur le feedback accumulé.
 * Les outils avec beaucoup de 👎 sont marqués comme "à utiliser avec prudence".
 */
export function getFeedbackHints(userId: string): string {
  const userFeedback = feedbackStore.filter((f) => f.userId === userId);
  if (userFeedback.length === 0) return "";

  const toolStats = new Map<string, { positive: number; negative: number }>();
  for (const f of userFeedback) {
    const stats = toolStats.get(f.toolName) ?? { positive: 0, negative: 0 };
    if (f.positive) stats.positive++;
    else stats.negative++;
    toolStats.set(f.toolName, stats);
  }

  const hints: string[] = [];
  for (const [tool, stats] of toolStats) {
    const total = stats.positive + stats.negative;
    if (total < 2) continue;
    const ratio = stats.positive / total;
    if (ratio < 0.3 && stats.negative >= 2) {
      hints.push(
        `L'utilisateur n'a pas apprécié les résultats de "${tool}" récemment — envisage d'autres approches.`,
      );
    } else if (ratio > 0.8 && stats.positive >= 3) {
      hints.push(`L'utilisateur apprécie particulièrement les résultats de "${tool}".`);
    }
  }

  return hints.length > 0 ? `\n\n[Hints feedback]: ${hints.join(" ")}` : "";
}

// ─── 3. Personal weekly digest ───────────────────────────────────────────────

interface UserDigestData {
  userId: string;
  messageCount: number;
  topChannels: string[];
  topToolsUsed: string[];
  questionsAsked: number;
  helpfulReactions: number;
}

/**
 * Collecte les données d'activité d'un utilisateur pour la semaine écoulée.
 */
async function collectUserDigestData(userId: string): Promise<UserDigestData | null> {
  try {
    const since = new Date(Date.now() - 7 * 86400_000);

    const messages = await prisma.chatHistory.findMany({
      where: { userId, createdAt: { gte: since } },
      orderBy: { createdAt: "desc" },
      take: 500,
    });

    if (messages.length === 0) return null;

    // Top channels
    const channelCounts = new Map<string, number>();
    for (const m of messages) {
      channelCounts.set(m.channelId, (channelCounts.get(m.channelId) ?? 0) + 1);
    }
    const topChannels = [...channelCounts.entries()]
      .sort((a, b) => b[1] - a[1])
      .slice(0, 3)
      .map(([c]) => c);

    // Count questions
    const questionsAsked = messages.filter((m) =>
      QUESTION_PATTERNS.some((p) => p.test(m.content)),
    ).length;

    // Feedback reactions
    const userFeedback = feedbackStore.filter((f) => f.userId === userId && f.timestamp >= since);
    const helpfulReactions = userFeedback.filter((f) => f.positive).length;

    // Tools used (from feedback)
    const topToolsUsed = [...new Set(userFeedback.map((f) => f.toolName))].slice(0, 5);

    return {
      userId,
      messageCount: messages.length,
      topChannels,
      topToolsUsed,
      questionsAsked,
      helpfulReactions,
    };
  } catch (err) {
    logger.debug(
      `[Digest] collectUserDigestData: ${err instanceof Error ? err.message : String(err)}`,
    );
    return null;
  }
}

/**
 * Génère et envoie un digest hebdomadaire à un utilisateur en DM.
 */
export async function sendPersonalDigest(client: Client, userId: string): Promise<boolean> {
  try {
    const data = await collectUserDigestData(userId);
    if (!data || data.messageCount < 5) return false;

    const embed = new EmbedBuilder()
      .setColor(0x5865f2)
      .setTitle("📊 Ton digest hebdomadaire")
      .setDescription("Voici un récapitulatif de ton activité cette semaine")
      .addFields(
        { name: "💬 Messages envoyés", value: String(data.messageCount), inline: true },
        { name: "❓ Questions posées", value: String(data.questionsAsked), inline: true },
        { name: "👍 Réactions positives", value: String(data.helpfulReactions), inline: true },
      )
      .setTimestamp();

    if (data.topToolsUsed.length > 0) {
      embed.addFields({
        name: "🔧 Outils utilisés",
        value: data.topToolsUsed.join(", "),
        inline: false,
      });
    }

    const dm = await client.users.send(userId, { embeds: [embed] }).catch(() => null);
    if (!dm) return false;

    logger.info(`[Digest] Digest hebdomadaire envoyé à ${userId}`);
    return true;
  } catch (err) {
    logger.debug(
      `[Digest] sendPersonalDigest: ${err instanceof Error ? err.message : String(err)}`,
    );
    return false;
  }
}

/**
 * Planificateur de digest hebdomadaire — envoie les digests le dimanche à 10h.
 */
let digestInterval: NodeJS.Timeout | null = null;

export function startPersonalDigestScheduler(client: Client): void {
  if (digestInterval) return;

  // Check every hour
  digestInterval = setInterval(
    async () => {
      const now = new Date();
      // Sunday = 0, between 10:00 and 10:59
      if (now.getDay() !== 0 || now.getHours() !== 10) return;

      logger.info("[Digest] Lancement du digest hebdomadaire personnel");

      // Get active users from the last week
      const since = new Date(Date.now() - 7 * 86400_000);
      const activeUsers = await prisma.chatHistory.findMany({
        where: { createdAt: { gte: since }, userId: { not: null } },
        select: { userId: true },
        distinct: ["userId"],
      });

      for (const { userId } of activeUsers) {
        if (!userId) continue;
        await sendPersonalDigest(client, userId);
        // Stagger sends to avoid rate limits
        await new Promise((r) => setTimeout(r, 2000));
      }

      logger.info(`[Digest] Digest hebdomadaire terminé (${activeUsers.length} utilisateurs)`);
    },
    60 * 60 * 1000,
  ); // Check hourly

  logger.info("[Digest] Planificateur de digest hebdomadaire démarré");
}

export function stopPersonalDigestScheduler(): void {
  if (digestInterval) {
    clearInterval(digestInterval);
    digestInterval = null;
    logger.info("[Digest] Planificateur de digest arrêté");
  }
}

import { Client, EmbedBuilder, TextChannel} from "discord.js";
import prisma from "../prisma.js";
import logger from "../utils/logger.js";
import { config } from "../config.js";
import { safeInterval } from "../utils/safe-interval.js";

let monitoringInterval: ReturnType<typeof setInterval> | null = null;

type Platform =
  | "twitch"
  | "youtube"
  | "twitter"
  | "instagram"
  | "tiktok"
  | "facebook"
  | "reddit"
  | "bluesky"
  | "mastodon"
  | "kick"
  | "telegram"
  | "snapchat"
  | "linkedin"
  | "pinterest"
  | "dailymotion"
  | "vimeo";

// ─── Twitch ──────────────────────────────────────────────────────────────────

let twitchToken: string | null = null;
let twitchTokenExpiry = 0;

async function getTwitchToken(): Promise<string> {
  if (twitchToken && Date.now() < twitchTokenExpiry - 60_000) return twitchToken;
  const res = await fetch(config.twitchOAuthUrl, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      client_id: config.twitchClientId,
      client_secret: config.twitchClientSecret,
      grant_type: "client_credentials",
    }),
  });
  if (!res.ok) throw new Error(`Twitch OAuth: ${res.status}`);
  const data = (await res.json()) as { access_token: string; expires_in: number };
  twitchToken = data.access_token;
  twitchTokenExpiry = Date.now() + (data.expires_in - 60) * 1000;
  return twitchToken;
}

async function checkTwitch(follows: typeof followsType): Promise<void> {
  const twitchFollows = follows.filter((f) => f.platform === "twitch");
  if (twitchFollows.length === 0) return;

  const logins = [...new Set(twitchFollows.map((f) => f.channelName.toLowerCase()))] as string[];
  let token: string;
  try {
    token = await getTwitchToken();
  } catch {
    logger.warn("[SocialFollow] Twitch token failed, skipping");
    return;
  }

  const params = logins.map((l) => `user_login=${encodeURIComponent(l)}`).join("&");
  const res = await fetch(`https://api.twitch.tv/helix/streams?${params}`, {
    headers: { "Client-ID": config.twitchClientId, Authorization: `Bearer ${token}` },
    signal: AbortSignal.timeout(10_000),
  });
  if (!res.ok) {
    logger.warn(`[SocialFollow] Twitch streams API: ${res.status}`);
    return;
  }

  const data = (await res.json()) as { data: Array<Record<string, unknown>> };
  const liveStreams = new Map(
    (data.data || []).map((s) => [(s.user_login as string)?.toLowerCase(), s]),
  );

  for (const follow of twitchFollows) {
    const stream = liveStreams.get(follow.channelName.toLowerCase());
    const isLive = !!stream;

    if (isLive && !follow.isLive) {
      await prisma.socialFollow.update({ where: { id: follow.id }, data: { isLive: true } });
      await sendNotification(follow, {
        title: `${stream.user_name as string} est en live sur Twitch !`,
        url: `https://twitch.tv/${follow.channelName}`,
        description:
          `**Jeu :** ${stream.game_name || "Inconnu"}\n` +
          `**Titre :** ${stream.title}\n` +
          `**Spectateurs :** ${(stream.viewer_count as number)?.toLocaleString() || "?"}`,
        thumbnail: (stream.thumbnail_url as string)
          ?.replace("{width}", "1280")
          .replace("{height}", "720"),
        color: 0x9146ff,
        footerText: "Twitch",
      });
    } else if (!isLive && follow.isLive) {
      await prisma.socialFollow.update({ where: { id: follow.id }, data: { isLive: false } });
    }
  }
}

// ─── YouTube ─────────────────────────────────────────────────────────────────

async function checkYouTube(follows: typeof followsType): Promise<void> {
  const ytFollows = follows.filter((f) => f.platform === "youtube");
  if (ytFollows.length === 0) return;

  if (!config.youtubeApiKey) {
    logger.debug("[SocialFollow] YouTube API key not configured, skipping");
    return;
  }

  for (const follow of ytFollows) {
    try {
      // Search for latest video from channel
      const searchUrl =
        `https://www.googleapis.com/youtube/v3/search?` +
        `key=${config.youtubeApiKey}&channelId=${follow.channelId}&` +
        `part=snippet&order=date&maxResults=1&type=video`;
      const res = await fetch(searchUrl, { signal: AbortSignal.timeout(10_000) });
      if (!res.ok) continue;
      const data = (await res.json()) as { items: Array<Record<string, unknown>> };
      const latestVideo = data.items?.[0];
      if (!latestVideo) continue;

      const videoId = (latestVideo.id as { videoId?: string })?.videoId;
      if (!videoId) continue;

      if (follow.lastVideoId && follow.lastVideoId === videoId) continue;

      const snippet = latestVideo.snippet as Record<string, unknown>;
      await prisma.socialFollow.update({
        where: { id: follow.id },
        data: { lastVideoId: videoId },
      });

      // Only notify if we had a previous video (skip first check to avoid spam)
      if (follow.lastVideoId) {
        await sendNotification(follow, {
          title: `Nouvelle vidéo: ${snippet.title as string}`,
          url: `https://youtube.com/watch?v=${videoId}`,
          description: `**Chaîne :** ${snippet.channelTitle as string}\n${(snippet.description as string)?.slice(0, 200) || ""}`,
          thumbnail: (snippet.thumbnails as { medium?: { url?: string } })?.medium?.url,
          color: 0xff0000,
          footerText: "YouTube",
        });
      }
    } catch (err) {
      logger.debug(`[SocialFollow] YouTube check failed for ${follow.channelName}: ${err}`);
    }
  }
}

// ─── Twitter / X ─────────────────────────────────────────────────────────────

async function checkTwitter(follows: typeof followsType): Promise<void> {
  const twFollows = follows.filter((f) => f.platform === "twitter");
  if (twFollows.length === 0) return;

  // Use Nitter RSS as fallback (no API key needed)
  const nitterInstances = ["https://nitter.privacydev.net", "https://nitter.poast.org"];

  for (const follow of twFollows) {
    let success = false;
    for (const instance of nitterInstances) {
      try {
        const res = await fetch(`${instance}/${follow.channelName}/rss`, {
          signal: AbortSignal.timeout(8_000),
          headers: { "User-Agent": "Mozilla/5.0" },
        });
        if (!res.ok) continue;
        const xml = await res.text();
        const tweetIds = [...xml.matchAll(/<guid>https:\/\/[^/]+\/[^/]+\/status\/(\d+)/g)]
          .map((m) => m[1])
          .filter(Boolean);
        if (tweetIds.length === 0) continue;

        const latestTweetId = tweetIds[0];
        if (follow.lastTweetId && follow.lastTweetId === latestTweetId) {
          success = true;
          break;
        }

        await prisma.socialFollow.update({
          where: { id: follow.id },
          data: { lastTweetId: latestTweetId },
        });

        // Only notify if we had a previous tweet
        if (follow.lastTweetId) {
          const titleMatch = xml.match(/<title>([^<]+)<\/title>/);
          const tweetTitle = titleMatch?.[1] || follow.channelName;
          await sendNotification(follow, {
            title: `Nouveau tweet de @${follow.channelName}`,
            url: `https://x.com/${follow.channelName}/status/${latestTweetId}`,
            description: tweetTitle.slice(0, 300),
            thumbnail: null,
            color: 0x1da1f2,
            footerText: "Twitter / X",
          });
        }
        success = true;
        break;
      } catch {
        // Try next instance
      }
    }
    if (!success) {
      logger.debug(`[SocialFollow] Twitter check failed for @${follow.channelName}`);
    }
  }
}

