 */
export async function vpsMaintenanceCheck(): Promise<{
  success: boolean;
  data: string;
}> {
  const disk = await getDiskInfo();

  let memInfo = "N/A";
  try {
    const { stdout: memOut } = await execFileAsync("free", ["-h"], { timeout: 5000 });
    const memLines = memOut.trim().split("\n").slice(0, 2).join("\n");
    memInfo = memLines;
  } catch {
    /* non-critical */
  }

  let loadAvg = "N/A";
  try {
    const loadOut = await readFile("/proc/loadavg", "utf-8");
    loadAvg = loadOut.trim();
  } catch {
    /* non-critical */
  }

  let topProcs = "N/A";
  try {
    const { stdout: topOut } = await execFileAsync("ps", ["aux", "--sort=-%mem"], {
      timeout: 5000,
    });
    const topLines = topOut.trim().split("\n").slice(0, 6).join("\n");
    topProcs = topLines;
  } catch {
    /* non-critical */
  }

  const diskStr = disk
    ? `${disk.used}/${disk.size} (${disk.usePercent}%) — ${disk.available} available`
    : "N/A";

  const status = disk
    ? disk.usePercent >= DISK_CRITICAL_THRESHOLD
      ? "🚨 CRITICAL"
      : disk.usePercent >= DISK_WARN_THRESHOLD
        ? "⚠️ WARNING"
        : "✅ HEALTHY"
    : "unknown";

  const data = JSON.stringify({
    disk: disk
      ? {
          used: disk.used,
          size: disk.size,
          available: disk.available,
          usePercent: disk.usePercent,
          filesystem: disk.filesystem,
        }
      : null,
    diskStatus: status,
    memory: memInfo,
    loadAverage: loadAvg,
    topProcesses: topProcs,
    uptime: process.uptime(),
    timestamp: new Date().toISOString(),
  });

  return { success: true, data };
}

/**
 * amazonToolkit.ts — Amazon monitoring utilities (wishlist scraping + Keepa API + cart + alerts)
 * Called by Quant (the AI brain) via tool handlers in agentToolsExtended.ts
 *
 * Tools:
 *  1. amazonWishlistScrape   — Scrape a public Amazon wishlist URL
 *  2. amazonPriceTrack        — Track price of an ASIN via Keepa API
 *  3. amazonPriceHistory      — Get price history chart data via Keepa
 *  4. amazonProductLookup      — Lookup product details by ASIN
 *  5. amazonCartMonitor        — Monitor cart via Puppeteer session
 *  6. amazonPriceAlertCreate   — Create a price drop alert
 *  7. amazonPriceAlertCheck    — Check active price alerts
 *  8. amazonPriceAlertDelete   — Delete a price alert
 *  9. amazonWishlistDiff       — Compare wishlist snapshots (added/removed/price changes)
