// ─── Code complexity analyzer ───────────────────────────────────────────────
export function codeComplexityAnalyzer(code: string, language: string): string {
  const lines = code.split("\n");
  const codeLines = lines.filter(
    (l) => l.trim() && !l.trim().startsWith("//") && !l.trim().startsWith("#"),
  );
  const branches = (code.match(/\b(if|else|for|while|switch|case|catch|&&|\|\|)\b/g) || []).length;
  const functions = (
    code.match(/\b(function|def|func|void|int|public|private|protected)\s+\w+\s*\(/g) || []
  ).length;
  const cyclomatic = branches + 1;
  const grade =
    cyclomatic <= 5
      ? "A (Simple)"
      : cyclomatic <= 10
        ? "B (Moderate)"
        : cyclomatic <= 20
          ? "C (Complex)"
          : "D (Very Complex)";
  return JSON.stringify(
    {
      language: language || "unknown",
      totalLines: lines.length,
      codeLines: codeLines.length,
      branches,
      functions,
      cyclomaticComplexity: cyclomatic,
      grade,
    },
    null,
    2,
  );
}

// ─── Code format beautifier ─────────────────────────────────────────────────
export function codeFormatBeautifier(code: string, _language: string): string {
  // Basic indentation beautifier
  let indent = 0;
  const indentSize = 2;
  const lines = code.split("\n");
  const formatted: string[] = [];
  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed.startsWith("}") || trimmed.startsWith("]") || trimmed.startsWith(")"))
      indent = Math.max(0, indent - 1);
    formatted.push(" ".repeat(indent * indentSize) + trimmed);
    if (trimmed.endsWith("{") || trimmed.endsWith("[") || trimmed.endsWith("(")) indent++;
  }
  return formatted.join("\n");
}

// ─── Code minifier ──────────────────────────────────────────────────────────
export function codeMinifier(code: string, _language: string): string {
  const minified = code
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/\/\/.*$/gm, "")
    .replace(/#.*$/gm, "")
    .replace(/\s+/g, " ")
    .replace(/\s*([{}();,:=<>+\-*/])\s*/g, "$1")
    .trim();
  const originalSize = code.length;
  const minifiedSize = minified.length;
  const reduction = ((1 - minifiedSize / originalSize) * 100).toFixed(1);
  return `${minified}\n\n--- ${originalSize} bytes -> ${minifiedSize} bytes (${reduction}% reduction) ---`;
}

// ─── Code diff unified ──────────────────────────────────────────────────────
export function codeDiffUnified(code1: string, code2: string): string {
  const lines1 = code1.split("\n");
  const lines2 = code2.split("\n");
  const maxLen = Math.max(lines1.length, lines2.length);
  const diff: string[] = [];
  for (let i = 0; i < maxLen; i++) {
    const l1 = lines1[i] || "";
    const l2 = lines2[i] || "";
    if (l1 === l2) {
      diff.push(`  ${l1}`);
    } else {
      if (l1) diff.push(`- ${l1}`);
      if (l2) diff.push(`+ ${l2}`);
    }
  }
  return diff.join("\n");
}

